const fs = require("node:fs");
const YAML = require("yaml");
const converter = require("swagger2openapi");

const swagger = YAML.parse(fs.readFileSync("swagger.yaml", "utf8"));

converter
  .convertObj(swagger, { patch: true, warnOnly: true })
  .then((options) => {
    fs.writeFileSync("openapi.yaml", YAML.stringify(options.openapi));
  });
